import {deliveryMapMarkup,observeDeliveryMaps} from './delivery-map.js';
import {authGate,authReady,session} from './auth-client.js';
await authReady;
import {renderAdmin} from './admin.js?v=3';
function financeStatus(order){return order.paymentStatus?`<p class="demo-note">Payment update: ${esc(order.paymentStatus)}. This is a recorded demo decision; no money has been transferred.</p>`:''}
import {renderAccessNotice} from './account-access.js';
import {effectiveOrder,accountRemoved,CUSTOMER_ID} from './portal-state.js';
import {renderDriver} from './driver.js?v=5';
function customerProgress(order,index){
 if(order.status==='Cancelled')return 'Cancelled';if(order.status==='Delivery Failed')return 'Not delivered';
 const level=({Accepted:0,'In Progress':0,'Picked Up':2,Completed:3})[order.driverStatus]??-1;
 if(index<level||index===0&&order.driverId)return 'Complete';
 if(index===level)return order.status;
 return index===0?order.status:'Pending';
}
import {installEnhancements} from './enhancements.js?v=5';
const $=s=>document.querySelector(s);
const app=$('#app');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const read=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}};
let draft=read('365-draft',{service:'Delivery',vehicle:'Box Truck',pickup:'',dropoff:'',date:'',time:'',stops:[],extras:[],notes:'',payment:'Credit/Debit Card'});
let orders=read('365-orders',[]),reviewIndex=0;
const portalPayments=['Credit/Debit Card','Apple Pay','Digital Wallet'];
function normalizePayment(){if(!portalPayments.includes(draft.payment))draft.payment='Credit/Debit Card'}
normalizePayment();
const saveDraft=()=>{normalizePayment();localStorage.setItem('365-draft',JSON.stringify(draft))};
const icon=(file,cls='')=>`<span class="icon ${cls}" aria-hidden="true"><img src="assets/${file}" alt=""></span>`;
const circle=(file)=>`<div class="circle">${icon(file)}</div>`;
const btn=(text,href,cls='')=>`<a class="btn ${cls}" href="${href}">${text}</a>`;
const brand=()=>`<a class="brand" href="#/" aria-label="365 Trucking home"><img src="assets/branding/365-trucking-updated.png" alt="365 Trucking"></a>`;
const navLink=(text,href)=>`<a href="${href}">${text}</a>`;
function header(customer=false){return `<header class="site-header ${customer?'app-header':''}"><div class="header-inner">${customer?'<a class="customer-brand" href="#/dashboard" aria-label="365 Trucking home"><img class="red-header-logo" src="assets/branding/365-trucking-silver-on-red.png" alt="365 Trucking"><img class="light-header-logo" src="assets/branding/365-trucking-updated.png" alt="365 Trucking"></a>':brand()}<nav id="nav" aria-label="Main navigation">${(customer? [['Home','#/dashboard'],['Book a Delivery','#/book/1'],['My Orders','#/orders'],['Track','#/track'],['Support','#/support']]:[['Home','#/'],['How It Works','#how-it-works'],['Vehicle Types','#vehicles'],['Contact','#contact']]).map(x=>navLink(...x)).join('')}</nav>${customer?`<div class="account-actions"><button data-action="notifications" aria-label="Notifications">${icon('55332.svg')}</button><button class="avatar-button" data-action="account" aria-label="Account menu">${icon('29ee2.svg')}</button></div>`:`<div class="auth"><a class="text-btn" href="#/login">Login</a>${btn('Sign Up','#/signup')}</div>`}<button class="menu-toggle" data-action="menu" aria-label="Toggle navigation" aria-expanded="false">☰</button></div></header>`}
function footer(full=false){return `<footer class="site-footer ${full?'full-footer':''}"><div class="container"><div class="footer-top"><div><img class="footer-logo" src="assets/branding/365-trucking-updated.png" alt="365 Trucking">${full?`<p>Your trusted partner for reliable delivery, moving, and courier services. Available 365 days a year to meet all your logistics needs.</p>${socials()}`:''}</div>${full?`<div><h3>Quick Links</h3><div class="footer-links"><a href="#/about">About Us</a><a href="#/services">Our Services</a><a href="#/pricing">Pricing</a><a href="#/areas">Service Areas</a></div></div><div><h3>Support</h3><div class="footer-links"><a href="#/support">Help & Support</a><a href="#/faq">FAQ</a><a href="#/contact">Contact Us</a><button data-action="chat" style="text-align:left;padding:0">Live Chat</button></div></div>`:`<div class="footer-links"><a href="#/">Home</a><a href="#/about">About</a><a href="#/faq">FAQs</a><a href="#/terms">Terms</a><a href="#/privacy">Privacy</a></div>${socials()}`}</div><div class="copyright">© 2027 365 Trucking. All rights reserved. <a class="text-btn" href="#/driver/login" style="margin-left:16px">Driver Portal</a> <a class="text-btn" href="#/admin/overview" style="margin-left:12px">Admin Portal</a>${full?` <span style="float:right"><a href="#/terms">Terms & Conditions</a>　 <a href="#/privacy">Privacy Policy</a></span>`:''}</div></div></footer>`}
function socials(){return `<div class="socials">${['035e7.svg','44856.svg','b9ce9.svg'].map((f,i)=>`<a href="#/contact" aria-label="${['Facebook','LinkedIn','Instagram'][i]}">${icon(f)}</a>`).join('')}</div>`}
const vehicleData=[['Box Truck','2ba3c.png','Perfect for large moves, furniture delivery, and commercial shipments up to 26 feet.',['Up to 10,000 lbs','Large items','Commercial moves'],'0b9bf.svg'],['Pickup Truck','27077.png','Great for construction materials, outdoor equipment, and bulky items.',['Up to 2,000 lbs','Open bed','Versatile loading'],'0b9bf.svg'],['Cargo Van','8e81e.png','Ideal for medium-sized deliveries, appliances, and small business shipments.',['Up to 4,000 lbs','Weather protected','Easy loading'],'0b9bf.svg'],['Sedan','5ce91.png','Perfect for documents, small packages, and quick courier services.',['Up to 100 lbs','Fast delivery','City navigation'],'1c5c0.svg']];
const reviews=[['Amazing service! They helped me move my entire office in just one day. The driver was professional and careful with all our equipment.','Sarah Johnson','Small Business Owner','13f99.png'],['Needed same-day furniture delivery and 365 Trucking came through perfectly. Great communication and fair pricing. Highly recommend!','Mike Chen','Homeowner','da40e.png'],['We use them regularly for our supply deliveries. Always on time, reliable, and the drivers are courteous. Excellent service every time.','Lisa Rodriguez','Restaurant Manager','41012.png']];
function review(){const r=reviews[reviewIndex];return `<div class="review-card"><div class="stars" aria-label="5 out of 5 stars">${Array(5).fill(icon('aa923.svg')).join('')}</div><blockquote>“${r[0]}”</blockquote><div class="review-person"><img src="assets/${r[3]}" alt="${r[1]}"><div><strong>${r[1]}</strong><small>${r[2]}</small></div></div></div><div class="dots" aria-label="Customer reviews">${reviews.map((_,i)=>`<button data-review="${i}" class="${i===reviewIndex?'active':''}" aria-label="Show review ${i+1}" aria-pressed="${i===reviewIndex}"></button>`).join('')}</div>`}
function landing(){app.innerHTML=`<main><section class="hero" id="home">${header()}<div class="container hero-body"><h1>Book Your Local Delivery or Moving Service Fast</h1><p>Connect instantly with nearby drivers for same-day or scheduled deliveries. Professional, reliable, and affordable.</p><div class="hero-actions">${btn('Book a Delivery','#/book/1')}${btn('How It Works','#how-it-works','white')}</div><form class="location-search" id="location-form"><div class="field"><label for="pickup">Pickup Location</label><div class="input-icon">${icon('8e577.svg')}<input id="pickup" name="pickup" autocomplete="street-address" required placeholder="Enter pickup address" value="${esc(draft.pickup)}"></div></div><div class="field"><label for="dropoff">Drop-off Location</label><div class="input-icon">${icon('995ba.svg')}<input id="dropoff" name="dropoff" required placeholder="Enter destination" value="${esc(draft.dropoff)}"></div></div><button class="btn" type="submit">${icon('33e76.svg')} Find Drivers</button></form></div></section><section class="section how" id="how-it-works"><div class="container"><h2>How It Works</h2><p class="subtitle">Get your delivery booked in just three simple steps</p><div class="steps">${[['e9519.svg','Enter Locations','Simply enter your pickup and drop-off locations to get started with your delivery request.'],['4ff11.svg','Choose Vehicle','Select the perfect vehicle type for your job - from sedans to box trucks.'],['333a8.svg','Get Matched','Get instantly connected with verified local drivers and moving professionals.']].map((x,i)=>`<article class="step"><span class="step-number">${i+1}</span>${circle(x[0])}<h3>${x[1]}</h3><p>${x[2]}</p></article>`).join('')}</div></div></section><section class="section vehicles" id="vehicles"><div class="container"><h2>Choose the Right Vehicle for Your Job</h2><p class="subtitle">From small packages to large moves, we have the perfect vehicle for<br> every delivery need</p><div class="vehicle-grid">${vehicleData.map(v=>`<a class="vehicle" href="#/book/1" data-vehicle="${v[0]}"><div class="vehicle-photo"><img src="assets/${v[1]}" alt="${v[0]}">${circle(v[4])}</div><div class="vehicle-copy"><h3>${v[0]}</h3><p>${v[2]}</p><ul>${v[3].map(t=>`<li>${icon('8a05f.svg')}${t}</li>`).join('')}</ul></div></a>`).join('')}</div></div></section><section class="section why"><div class="container"><h2>Why 365 Trucking?</h2><p class="subtitle">We're committed to providing the best delivery and moving experience</p><div class="benefits">${[['bee49.svg','Fast & Reliable Deliveries','Same-day and scheduled delivery options with real-time tracking and updates.'],['333a8.svg','Trained Moving Professionals','All drivers are background-checked, insured, and trained for safe handling.'],['839e4.svg','Transparent Pricing','No hidden fees. Get upfront pricing with detailed breakdowns before booking.'],['4d298.svg','Real-Time Tracking','Track your delivery in real-time and communicate directly with your driver.']].map(x=>`<article class="benefit">${circle(x[0])}<h3>${x[1]}</h3><p>${x[2]}</p></article>`).join('')}</div></div></section><section class="section reviews"><div class="container"><h2>What Our Customers Say</h2><p class="subtitle">Don't just take our word for it - hear from our satisfied customers</p><div id="review">${review()}</div></div></section><section class="section cta" id="contact"><h2>Ready to Book Your Delivery?</h2><p class="subtitle">Join a growing network of customers who count on 365 Trucking to get the job done.</p><div class="cta-actions">${btn('Get a Quote Now','#/book/1')}<a class="btn white" href="tel:+19736987272">${icon('3abd4.svg')}Call Us: 973-698-7272</a></div><div class="stats"><div><strong>24/7</strong><span>Available Service</span></div><div><strong>5000+</strong><span>Successful Deliveries</span></div><div><strong>4.9★</strong><span>Customer Rating</span></div></div></section></main>${footer()}`;$('#location-form').onsubmit=e=>{e.preventDefault();draft.pickup=$('#pickup').value.trim();draft.dropoff=$('#dropoff').value.trim();saveDraft();go('/book/1')};}
function go(path){if(location.hash==='#'+path)render();else location.hash=path}
function field(label,name,type='text',required=false,value=draft[name]||''){return `<div class="field"><label for="${name}">${label}${required?' *':''}</label><input id="${name}" name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${type==='date'?`min="${new Date().toLocaleDateString('en-CA')}"`:''}></div>`}
function progress(step){return `<div class="progress-wrap"><div class="progress-inner"><div class="progress-label"><strong>Book Your Service</strong><span>Step ${step} of 4</span></div><div class="progress-bar"><i style="width:${step*25}%"></i></div></div></div>`}
function choice(text,sub,value,name,extra=''){return `<button type="button" class="choice ${draft[name]===value?'selected':''} ${extra}" data-choice="${name}" data-value="${value}" aria-pressed="${draft[name]===value}">${text}<small>${sub}</small>${extra?'':'<span class="radio-dot"></span>'}</button>`}
function routeAddresses(p=draft.pickup,d=draft.dropoff){return `<div class="route-addresses"><p>Pickup<span>${esc(p||'Enter pickup address')}</span></p><p>Drop-off<span>${esc(d||'Enter drop-off address')}</span></p></div>`}
function step1(){return `<h1>What do you want to book today?</h1><p class="muted">Choose your service type and select the perfect vehicle for your needs</p><h2>Select Service</h2><div class="choice-grid">${[['Delivery','Package and item delivery','efd79.svg'],['Moving','Residential and office moving','9715a.svg'],['Courier','Fast document delivery','54c97.svg']].map(x=>choice(`<span class="service-symbol" aria-hidden="true">${icon(x[2])}</span><strong>${x[0]}</strong>`,x[1],x[0],'service','service-choice')).join('')}</div><h2>Choose Vehicle Type</h2><div class="choice-grid">${[['Cargo Van','$45-65','Perfect for packages & small items'],['Pickup Truck','$55-75','Great for furniture & appliances'],['Box Truck','$85-120','Large deliveries & bulk items']].map(x=>choice(`<div class="choice-top"><strong>${x[0]}</strong><span>${x[1]}</span></div>`,x[2],x[0],'vehicle')).join('')}</div>`}
function step2(){return `<h1>Pickup & Drop Locations</h1><p class="muted">Add your pickup and delivery addresses with schedule</p><div class="two-cols"><div class="form-stack">${field('Pickup Address','pickup','text',true)}${field('Drop-off Address','dropoff','text',true)}<div class="label-row">Additional Stops (Optional)<button type="button" class="text-btn" data-action="add-stop">+ Add Another Stop</button></div><div id="stops" class="form-stack">${draft.stops.map((s,i)=>`<div class="stop"><input aria-label="Additional stop ${i+1}" name="stop-${i}" value="${esc(s)}" required><button type="button" data-remove-stop="${i}" aria-label="Remove stop ${i+1}">×</button></div>`).join('')}</div><div class="form-row">${field('Pickup Date','date','date',true)}${field('Pickup Time','time','time',true)}</div></div><div class="route-preview"><div class="circle">${icon('c7286.svg')}</div><h2 style="margin:0">Route Preview</h2><p class="muted">Map will show your pickup and drop-off locations</p><div id="route-addresses" style="width:100%">${routeAddresses()}</div></div></div>`}
const extraOptions=[['fragile','Fragile Items','Extra care for delicate items',15],['helpers','Need Extra Helpers','Additional crew for heavy lifting',25],['packing','Include Packing Service','Professional packing materials',20]];
function step3(){return `<h1>Add Delivery Details</h1><p class="muted">Tell us more about your delivery requirements</p><h2>Service Options</h2><div class="form-stack">${extraOptions.map(x=>`<label class="check-option"><input type="checkbox" name="extras" value="${x[0]}" ${draft.extras.includes(x[0])?'checked':''}><span>${x[1]}<small>${x[2]}</small></span></label>`).join('')}<div><h2>Upload Photos (Optional)</h2><div class="upload"><p>Drag and drop photos here, or</p><input type="file" id="photos" accept="image/*" multiple aria-label="Browse Files"><p class="muted">Maximum 5 photos, up to 10MB each</p><div id="photo-list"></div></div></div><div class="field"><label for="notes">Notes for Driver</label><textarea id="notes" name="notes" rows="5" maxlength="500" placeholder="Any special instructions for your driver?">${esc(draft.notes)}</textarea><small class="muted" id="note-count">${draft.notes.length}/500 characters</small></div></div>`}
function fare(){const base={'Cargo Van':45,'Pickup Truck':55,'Box Truck':85,'Sedan':25}[draft.vehicle]||85;const extras=extraOptions.filter(x=>draft.extras.includes(x[0]));return {base,extras,total:base+extras.reduce((a,x)=>a+x[3],0)}}
function summaryBox(title,body,step){return `<section class="summary-box"><div class="summary-title"><strong>${title}</strong><a class="text-btn" href="#/book/${step}">Edit</a></div>${body}</section>`}
function step4(){const f=fare();return `<h1>Review & Payment</h1><p class="muted">Review your booking details and choose payment method</p><div class="two-cols"><div><h2>Booking Summary</h2>${summaryBox('Service & Vehicle',`${esc(draft.service)} - ${esc(draft.vehicle)}`,1)}${summaryBox('Locations',routeAddresses(),2)}${summaryBox('Schedule',`${esc(draft.date)} at ${esc(draft.time)}`,2)}${summaryBox('Extras',extraOptions.filter(x=>draft.extras.includes(x[0])).map(x=>`<p>• ${x[1]}</p>`).join('')||'No extras selected',3)}<section class="summary-box fare"><strong>Fare Breakdown</strong><div class="fare-row"><span>Base fare</span><span>$${f.base}</span></div>${f.extras.map(x=>`<div class="fare-row"><span>${x[1]}</span><span>$${x[3]}</span></div>`).join('')}<div class="fare-row total"><span>Total</span><span>$${f.total}</span></div></section></div><div><h2>Payment Method</h2><div class="payment-options">${[['Credit/Debit Card','Visa, Mastercard, American Express'],['Apple Pay','Quick and secure payment'],['Digital Wallet','PayPal, Google Pay']].map(x=>`<button type="button" class="choice payment-choice ${draft.payment===x[0]?'selected':''}" data-choice="payment" data-value="${x[0]}" aria-pressed="${draft.payment===x[0]}"><div><strong>${x[0]}</strong><small>${x[1]}</small></div><span class="radio-dot"></span></button>`).join('')}</div><p class="demo-note">Prototype booking: no payment will be collected and no driver will be dispatched. Prices are illustrative estimates based on the design.</p></div></div>`}
function capture(){const form=$('#booking-form');if(!form)return;const fd=new FormData(form);for(const k of ['pickup','dropoff','date','time','notes'])if(fd.has(k))draft[k]=String(fd.get(k));if(form.querySelector('[name="extras"]'))draft.extras=fd.getAll('extras');if(form.querySelector('#stops'))draft.stops=[...form.querySelectorAll('[name^="stop-"]')].map(x=>x.value);saveDraft()}
function booking(step){normalizePayment();app.innerHTML=`${header(true)}${progress(step)}<main class="booking-main"><form class="booking-card" id="booking-form">${[step1,step2,step3,step4][step-1]()}<div class="form-actions">${btn(step===1?'Back to Dashboard':'Back',step===1?'#/dashboard':`#/book/${step-1}`,'outline')}<button class="btn" type="submit">${['Next → Add Locations','Next → Add Details','Next → Review Booking','Confirm Booking'][step-1]}</button></div></form></main>${footer(true)}`;$('#booking-form').onsubmit=e=>{e.preventDefault();if(accountRemoved(localStorage,CUSTOMER_ID)){render();return}capture();if(step===2){if(draft.pickup.trim().toLowerCase()===draft.dropoff.trim().toLowerCase()){toast('Pickup and drop-off must be different addresses.');return}if(new Date(`${draft.date}T${draft.time}`)<new Date()){toast('Please choose a future pickup date and time.');return}}if(step<4)go(`/book/${step+1}`);else{if(!draft.pickup||!draft.dropoff||!draft.date||!draft.time){toast('Complete the pickup, drop-off and schedule before confirming.');go('/book/2');return}normalizePayment();const order={...draft,customerId:CUSTOMER_ID,customerName:read('365-profile',{}).name||'Local Customer',id:'TRK-'+crypto.randomUUID().slice(0,8).toUpperCase(),total:fare().total,status:'Booking Confirmed',createdAt:new Date().toISOString(),demo:true};orders.unshift(order);localStorage.setItem('365-orders',JSON.stringify(orders));go('/confirmed/'+order.id)}};$('#booking-form').addEventListener('input',()=>{capture();if(step===2)$('#route-addresses').innerHTML=routeAddresses();if(step===3)$('#note-count').textContent=draft.notes.length+'/500 characters'});if(step===3)$('#photos').onchange=e=>{const files=[...e.target.files];if(files.length>5||files.some(x=>x.size>10*1024*1024)){toast('Choose up to 5 images, each smaller than 10MB.');e.target.value='';return}$('#photo-list').textContent=files.map(x=>x.name).join(', ');toast('Photos selected for this preview. Upload storage is not connected.')}}
function confirmed(id){const o=orders.find(x=>x.id===id);if(!o){go('/orders');return}app.innerHTML=`${header(true)}<main class="booking-main"><div class="confirmation"><div class="success">✓</div><h1>Your Booking is Confirmed!</h1><p class="muted">Your demo booking has been saved on this device.</p><p class="demo-note">This is a prototype confirmation. No real delivery has been requested.</p><div class="two-cols"><section class="summary-box"><h2>Booking Details</h2><p>Booking ID: <strong>${o.id}</strong></p><p>Service: ${esc(o.service)}</p><p>Vehicle: ${esc(o.vehicle)}</p><p>Date & Time: ${esc(o.date)} at ${esc(o.time)}</p></section><section class="summary-box"><h2>Route Summary</h2>${routeAddresses(o.pickup,o.dropoff)}<div class="fare-row total"><span>Total Fare:</span><span>$${o.total}</span></div></section></div><h2 style="margin:32px 0">What's Next?</h2><ul class="timeline"><li><b>✓</b><div>Booking Confirmed<small>Your request has been saved locally</small></div></li><li><b>2</b><div>Driver Assignment<small>Available after dispatch services are connected</small></div></li><li><b>3</b><div>Driver En Route<small>Live tracking requires GPS integration</small></div></li></ul><div class="cta-actions" style="margin-top:40px">${btn('Track My Order','#/track/'+o.id)}${btn('Back to Home','#/dashboard','outline')}</div></div></main>${footer(true)}`}
function orderCard(o){return `<article class="order-card"><div class="order-heading"><div><strong>#${esc(o.id)}</strong><p class="muted">${esc(o.vehicle)}</p></div><span class="badge">${esc(o.status)}</span></div>${routeAddresses(o.pickup,o.dropoff)}<p class="muted">${esc(o.date)} at ${esc(o.time)}　·　$${o.total}</p><p class="demo-note">Demo booking stored on this device</p>${financeStatus(o)}<div class="form-actions">${btn('Track Order','#/track/'+o.id)}${['Cancelled','Delivered','Delivery Failed'].includes(o.status)?`<button data-rebook="${o.id}" class="text-btn">Rebook</button>`:`<button data-cancel="${o.id}" class="text-btn">Cancel</button>`}</div></article>`}
function ordersPage(){app.innerHTML=`${header(true)}<main class="page-main"><h1>My Orders</h1><p class="muted">View and manage all your active and completed deliveries.</p><div class="page-toolbar"><input id="order-search" placeholder="Search by order ID, date, or destination..." aria-label="Search orders"><select id="order-filter" aria-label="Filter orders"><option>All Orders</option><option>Active</option><option>Cancelled</option></select>${btn('Book a Delivery','#/book/1')}</div><div id="order-results"></div></main>${footer(true)}`;const filter=()=>{const q=$('#order-search').value.toLowerCase(),f=$('#order-filter').value;const data=orders.filter(o=>JSON.stringify(o).toLowerCase().includes(q)&&(f==='All Orders'||(f==='Cancelled'?o.status==='Cancelled':!['Cancelled','Delivered','Delivery Failed'].includes(o.status))));$('#order-results').innerHTML=data.length?`<div class="order-list">${data.map(orderCard).join('')}</div>`:`<div class="empty-state"><h2>${orders.length?'No matching orders':'No orders yet'}</h2><p class="muted">${orders.length?'Try another search or filter.':'Your bookings will appear here when you complete your first delivery request.'}</p></div>`};$('#order-search').oninput=filter;$('#order-filter').onchange=filter;filter()}
function tracking(id=''){const o=orders.find(x=>x.id===id),sample=id==='TRK-2024-001';app.innerHTML=header(true);if(!id||(!o&&!sample)){app.innerHTML+=`<main class="page-main"><form class="page-toolbar" id="track-form"><input name="tracking" placeholder="Enter tracking ID..." required value="${esc(id)}" aria-label="Tracking ID"><button class="btn">Track</button></form><div class="empty-state"><div class="success">♧</div><h1>${id?'Tracking ID Not Found':'No Active Shipments'}</h1><p class="muted">${id?'Check the tracking ID and try again. This prototype can find bookings saved on this device and the sample delivery.':"You don't have any active shipments right now. Enter a tracking ID above or book a new delivery to get started."}</p><div class="cta-actions">${btn('Book a Delivery','#/book/1')}${btn('View My Orders','#/orders','outline')}</div><a class="sample-id" href="#/track/TRK-2024-001">Try tracking with sample ID: TRK-2024-001</a><h3>Track with Confidence</h3><p class="muted">Real-time GPS tracking · Direct driver communication · Live delivery updates</p><p class="demo-note">The sample delivery is a design preview, not a live shipment.</p></div></main>${footer(true)}`;$('#track-form').onsubmit=e=>{e.preventDefault();go('/track/'+encodeURIComponent(new FormData(e.target).get('tracking').trim().replace(/^#/,'')))};return}const order=o||{id,service:'Express Delivery',date:'2024-01-15',time:'10:30 AM',status:'In Transit',pickup:'123 Business District, Dubai Marina, Dubai',dropoff:'456 Residential Area, Jumeirah Beach Residence, Dubai'};app.innerHTML+=`<main class="tracking-layout">${deliveryMapMarkup({sample})}<aside class="tracking-panel"><section class="panel"><h2>Order Summary</h2><p>Order ID: <strong>#${esc(order.id)}</strong></p><p>Service: <strong>${esc(order.service)}</strong></p><p>Date & Time: ${esc(order.date)} at ${esc(order.time)}</p></section><section class="panel"><h2>Driver Information</h2>${sample?`<div class="driver"><img src="assets/f4463.png" alt="Ahmed Hassan"><div><strong>Ahmed Hassan</strong><small>⭐ 4.8</small><small>Medium Truck • DXB-T-1234</small></div></div><div class="cta-actions"><button class="btn" data-action="driver-call" style="background:#16a34a">Call Driver</button><button class="btn" data-action="driver-message">Message</button></div>`:`<p class="muted">${order.status==='Cancelled'?'This demo booking was cancelled.':order.driverName?'Assigned driver: '+esc(order.driverName)+' · '+esc(order.driverStatus||order.status)+' (local demo)':'A driver has not been assigned. Dispatch services are not connected.'}</p>`}</section><section class="panel"><h2>Delivery Progress</h2><ul class="timeline">${[['Order Accepted','10:30 AM'],['Picked Up','11:15 AM'],['In Transit','12:00 PM'],['Delivered','2:30 PM (Est.)']].map((x,i)=>`<li><b style="${i===2&&sample?'background:#dc2626;color:white':''}">${sample&&i<2?'✓':i+1}</b><div>${x[0]}<small>${sample?x[1]:customerProgress(order,i)}</small></div></li>`).join('')}</ul></section><section class="panel"><h2>Route Details</h2>${routeAddresses(order.pickup,order.dropoff)}${financeStatus(order)}</section><p class="demo-note">${sample?'Sample data from the Figma design. The map, driver and progress are illustrative.':'This booking is saved locally. Live dispatch and GPS are not connected.'}</p>${o&&!['Cancelled','Delivered','Delivery Failed'].includes(o.status)?`<button class="btn outline" data-cancel="${o.id}">Cancel Delivery</button>`:''}<a class="btn outline" href="#/support">Report an Issue</a></aside></main>`}
function login(signup=false){app.innerHTML=`<main class="login-layout"><section class="login-visual"><div><h2>Fast, Reliable, and Local Deliveries</h2><p>Connect instantly with nearby drivers for same-day or scheduled deliveries. Your trusted partner for all moving and courier needs.</p></div></section><section class="login-form-wrap"><a class="login-home" href="#/">Back to Home</a><form class="login-form" id="login-form"><h1>${signup?'Create Your Account':'Welcome Back'}</h1><p class="muted">${signup?'Get started with 365 Trucking.':'Sign in to book your delivery or manage existing orders.'}</p><div class="form-stack">${signup?field('Full Name','name','text',true,''):''}${field('Email Address','email','email',true,'')}${field('Password','password','password',true,'')}</div><div class="label-row"><label><input type="checkbox"> Remember me</label><button type="button" class="text-btn" data-action="forgot">Forgot Password?</button></div><button class="btn">${signup?'Create Demo Profile':'Sign In to Demo'}</button><p class="demo-note">Prototype access only. No real account is created. Do not enter a password you use elsewhere.</p><p class="login-bottom">${signup?'Already have an account?':'Don’t have an account?'} <a class="text-btn" href="#/${signup?'login':'signup'}">${signup?'Sign in':'Sign up here'}</a></p></form></section></main>`;$('#password').minLength=8;$('#password').autocomplete=signup?'new-password':'current-password';$('#login-form').onsubmit=e=>{e.preventDefault();const fd=new FormData(e.target);localStorage.setItem('365-profile',JSON.stringify({name:fd.get('name')||'Customer',email:fd.get('email')}));go('/dashboard')};}
function dashboard(){const p=read('365-profile',{name:'John'});app.innerHTML=`<div class="dashboard-header">${header(true)}</div><main class="dashboard"><section class="dashboard-hero"><h1>Welcome, ${esc(p.name.split(' ')[0])}!</h1><p>Start booking your services now and experience reliable delivery,<br> moving, and courier solutions.</p><div class="cta-actions">${btn('Book a Delivery','#/book/1')}${btn('View Past Orders','#/orders','white')}</div></section><section class="section dashboard-services"><div class="container"><h2>Choose a Service</h2><p class="subtitle">Select from our comprehensive range of logistics solutions designed to meet all your delivery and moving needs.</p><div class="dashboard-grid">${[['Delivery','f0767.png','Fast and reliable package delivery services for businesses and individuals.'],['Moving','5ce96.png','Complete residential and commercial moving solutions with professional care.'],['Courier','f41e2.png','Express courier services for urgent documents and small packages.']].map(x=>`<article class="vehicle"><img class="service-photo" src="assets/${x[1]}" alt="${x[0]} service"><div class="vehicle-copy"><h3>${x[0]}</h3><p>${x[2]}</p><a class="btn" href="#/book/1" data-service="${x[0]}">Book Now</a></div></article>`).join('')}</div></div></section><section class="section dashboard-section"><div class="container"><h2>Quick Actions</h2><p class="subtitle">Access your most-used features quickly and efficiently.</p><div class="dashboard-grid">${[['Track My Order','Get real-time updates on your active deliveries','#/track','#2563eb','a930b.svg'],['Manage Profile','Update personal information and payment methods','#/profile','#16a34a','ae822.svg'],['Request Support','Get help from our customer service team','#/support','#9333ea','b3368.svg']].map(x=>`<article class="quick-card"><div class="circle" style="background:${x[3]}">${icon(x[4])}</div><h3>${x[0]}</h3><p>${x[1]}</p><a class="btn" style="background:${x[3]}" href="${x[2]}">Get Started</a></article>`).join('')}</div></div></section><section class="section dashboard-orders"><div class="container"><h2>Your Orders</h2><p class="subtitle">Track your current deliveries and view your order history.</p><div class="two-cols"><div class="panel"><h3>Active Booking</h3>${orders.some(o=>!['Cancelled','Delivered','Delivery Failed'].includes(o.status))?orderCard(orders.find(o=>!['Cancelled','Delivered','Delivery Failed'].includes(o.status))):`<div class="empty-state"><p>No active bookings</p>${btn('Book a Delivery','#/book/1')}</div>`}</div><div class="panel"><div class="order-heading"><h3>Recent Orders</h3><a class="text-btn" href="#/orders">View All Orders</a></div>${orders.length?orders.slice(0,3).map(o=>`<a class="recent-order" href="#/track/${o.id}"><strong>${esc(o.service)} - ${o.id}</strong><span class="badge">${o.status}</span><p class="muted">${esc(o.pickup)} → ${esc(o.dropoff)}</p></a>`).join(''):`<p class="muted">Your completed and cancelled deliveries will appear here.</p>`}</div></div></div></section><section class="section dashboard-section"><div class="container"><h2>Exclusive Offers</h2><p class="subtitle">Take advantage of our special promotions and save on your next booking.</p><div class="dashboard-grid">${[['dfbdb.png','First-Time User Special','Get free pickup service on your first delivery booking. Valid for new customers only.'],['6ba05.png','Moving Package Deal','Save 25% on residential moving services when you book a full-service package.'],['a4483.png','Express Courier Discount','Same-day courier delivery at reduced rates for business customers.']].map(x=>`<article class="offer"><img src="assets/${x[0]}" alt="${x[1]}"><div><h3>${x[1]}</h3><p>${x[2]}</p><small>Design sample • promotion not active</small><button class="btn" data-action="offer">Learn More</button></div></article>`).join('')}</div><div class="dashboard-ready"><h2>Ready to Get Started?</h2><p>Join thousands of satisfied customers who trust 365 Trucking for their delivery and moving needs.</p>${btn('Book Your Service Now','#/book/1')}</div></div></section></main>${footer(true)}`}
function info(page){const content={about:['About 365 Trucking','Local delivery, moving, and courier services.'],services:['Our Services','Choose Delivery, Moving, or Courier and select a vehicle that fits your needs.'],pricing:['Pricing','Choose a service and vehicle to view an illustrative fare estimate before confirming your booking.'],areas:['Service Areas','Service-area availability will be connected to the booking system.'],faq:['Frequently Asked Questions','How do I book a delivery?','Choose a service and vehicle, enter your pickup and drop-off addresses, add delivery details, and review your booking.'],support:['Support & Feedback','How can we help you?'],contact:['Contact Us','Call Us: 973-698-7272'],terms:['Terms & Conditions','Terms of service content has not been supplied.'],privacy:['Privacy Policy','Production privacy policy content has not been supplied. This prototype saves bookings and profile information in this browser.']};const c=content[page]||content.support;app.innerHTML=`${header(true)}<main class="page-main"><h1>${c[0]}</h1><p class="muted">${c[1]}</p>${c[2]?`<p style="margin-top:24px">${c[2]}</p>`:''}${['support','contact'].includes(page)?`<form class="booking-card" id="support-form" style="margin-top:40px"><h2>Send a Message</h2><div class="form-stack">${field('Email Address','support-email','email',true,'')}${field('Subject','subject','text',true,'')}<div class="field"><label for="message">Message</label><textarea id="message" required rows="6"></textarea></div><button class="btn">Save Draft</button></div><p class="demo-note">Support messaging is not connected. You can save a draft locally.</p></form>`:''}</main>${footer(true)}`;if($('#support-form'))$('#support-form').onsubmit=e=>{e.preventDefault();localStorage.setItem('365-support-draft',JSON.stringify({email:$('#support-email').value,subject:$('#subject').value,message:$('#message').value}));toast('Support draft saved on this device. It has not been sent.')};}
function toast(message){$('.toast')?.remove();const el=document.createElement('div');el.className='toast';el.role='status';el.textContent=message;document.body.append(el);setTimeout(()=>el.remove(),6000)}
function modal(title,text,confirm){$('dialog')?.remove();const d=document.createElement('dialog');d.innerHTML=`<h2>${esc(title)}</h2><p>${esc(text)}</p><div class="cta-actions"><button class="btn" id="modal-confirm">${confirm?'Confirm':'Close'}</button>${confirm?'<button class="btn outline" id="modal-close">Keep Booking</button>':''}</div>`;document.body.append(d);d.showModal();$('#modal-confirm').onclick=()=>{d.close();d.remove();confirm?.()};if($('#modal-close'))$('#modal-close').onclick=()=>{d.close();d.remove()}}
document.addEventListener('click',e=>{const v=e.target.closest('[data-vehicle]');if(v){draft.vehicle=v.dataset.vehicle;saveDraft()}const r=e.target.closest('[data-review]');if(r){reviewIndex=+r.dataset.review;$('#review').innerHTML=review()}const c=e.target.closest('[data-choice]');if(c){capture();draft[c.dataset.choice]=c.dataset.value;saveDraft();const pos=scrollY;render(false);scrollTo(0,pos)}const remove=e.target.closest('[data-remove-stop]');if(remove){capture();draft.stops.splice(+remove.dataset.removeStop,1);saveDraft();render(false)}const cancel=e.target.closest('[data-cancel]');if(cancel)modal('Cancel this delivery?','This will cancel the demo booking saved on this device.',()=>{const o=orders.find(x=>x.id===cancel.dataset.cancel);if(o)o.status='Cancelled';localStorage.setItem('365-orders',JSON.stringify(orders));render(false);toast('Demo booking cancelled.')});const rebook=e.target.closest('[data-rebook]');if(rebook){draft={...orders.find(x=>x.id===rebook.dataset.rebook),date:'',time:''};saveDraft();go('/book/1')}const zoom=e.target.closest('[data-zoom]');if(zoom){const map=$('#map');let size=+(map.dataset.zoom||100);size=zoom.dataset.zoom==='0'?100:Math.max(100,Math.min(180,size+Number(zoom.dataset.zoom)*20));map.dataset.zoom=size;map.style.backgroundSize=size===100?'cover':size+'%'}const a=e.target.closest('[data-action]');if(!a)return;switch(a.dataset.action){case'menu':$('#nav').classList.toggle('open');a.setAttribute('aria-expanded',$('#nav').classList.contains('open'));break;case'add-stop':capture();if(draft.stops.length>=5){toast('Up to 5 additional stops are supported.');break}draft.stops.push('');saveDraft();render(false);break;case'account':if($('.app-menu')){$('.app-menu').remove();break}a.insertAdjacentHTML('afterend',`<div class="app-menu"><a href="#/profile">My Profile</a><a href="#/orders">My Orders</a><a href="#/notifications">Notifications</a><a href="#/auth/signout">Sign Out</a></div>`);break;case'notifications':go('/notifications');break;case'forgot':modal('Password recovery','Authentication is not connected in this prototype. You can access the demo with any valid email and a temporary password of at least 8 characters.');break;case'driver-call':case'driver-message':modal('Sample driver','This driver is sample data from the design. Live calls and messages are not connected.');break;case'chat':modal('Live Chat','Support chat will be available after the support service is connected.');break;}});
function render(reset=true){orders=read('365-orders',[]).map(order=>effectiveOrder(localStorage,order));document.title='365 Trucking | Local Delivery & Moving';const hash=location.hash.slice(1)||'/';if(!hash.startsWith('/')){if(!app.children.length)landing();document.getElementById(hash)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});return}if(authGate(app,hash))return;const parts=hash.split('/').filter(Boolean),page=parts[0]||'';if(['dashboard','book','orders','track','profile','notifications','login','signup'].includes(page)&&renderAccessNotice(app,'Customer'))return;switch(page){case'admin':renderAdmin({app,segments:parts.slice(1),helpers:{toast,modal}});break;case'driver':renderDriver({app,segments:parts.slice(1),helpers:{toast,modal}});break;case'':landing();break;case'book':booking(Math.max(1,Math.min(4,Number(parts[1])||1)));break;case'confirmed':confirmed(parts[1]);break;case'orders':ordersPage();break;case'track':tracking(decodeURIComponent(parts[1]||''));break;case'login':login();break;case'signup':login(true);break;case'dashboard':dashboard();break;case'profile':profilePage();break;case'notifications':notificationsPage();break;default:info(page)}observeDeliveryMaps();if(session){app.insertAdjacentHTML('beforeend','<aside class="auth-session-bar">'+(hash.startsWith('/admin/documents')||hash==='/driver/documents'?'Private document workspace':'Signed in with Supabase · App data is a local demo')+' <a href="#/auth/signout">Sign out</a></aside>')}if(reset)scrollTo(0,0)}
function profilePage(){const p=read('365-profile',{name:'Customer',email:''});app.innerHTML=`${header(true)}<main class="page-main"><h1>Personal Information</h1><p class="muted">Manage your profile details.</p><form class="booking-card" id="profile-form" style="margin-top:32px"><div class="form-stack">${field('Full Name','profile-name','text',true,p.name)}${field('Email Address','profile-email','email',true,p.email)}<button class="btn">Save Changes</button></div><p class="demo-note">Profile details are saved on this device only.</p></form></main>${footer(true)}`;$('#profile-form').onsubmit=e=>{e.preventDefault();localStorage.setItem('365-profile',JSON.stringify({name:$('#profile-name').value,email:$('#profile-email').value}));toast('Profile saved on this device.')}}
function notificationsPage(){app.innerHTML=`${header(true)}<main class="page-main"><h1>Notifications</h1><p class="muted">Delivery updates and account activity.</p><div class="empty-state"><h2>No notifications yet</h2><p class="muted">Live delivery notifications will appear here after backend services are connected.</p></div></main>${footer(true)}`}
installEnhancements({onService:service=>{draft.service=service;saveDraft()},onOffer:()=>modal('Sample promotion','This promotion is shown from the Figma design. It is not active and does not change the fare estimate.')});
window.addEventListener('storage',event=>{if(['365-orders','365-admin-state','365-driver-job-state'].includes(event.key))render(false)});window.addEventListener('hashchange',()=>render());window.addEventListener('365-auth-change',()=>render(false));render();
